import React, { useEffect, useMemo, useRef, useState } from 'react';
import { savePlaybackProgress, getPlaybackProgress } from '../../history/playbackProgress';

const StreamingPlayer = ({ sources = [], identity, metadata = {}, subtitles = [] }) => {
  const videoRef = useRef(null);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [notice, setNotice] = useState('');
  const source = sources[selectedIndex] || sources[0];
  const progress = useMemo(() => getPlaybackProgress(identity), [identity]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video || !source) return undefined;
    setNotice('');

    if (source.sourceType === 'hls' && !video.canPlayType('application/vnd.apple.mpegurl')) {
      setNotice('This browser does not provide native HLS playback. Use an MP4 source or a browser with native HLS support.');
    }

    const restore = () => {
      if (progress?.currentTime && progress.currentTime < video.duration) video.currentTime = progress.currentTime;
    };
    video.addEventListener('loadedmetadata', restore, { once: true });
    return () => video.removeEventListener('loadedmetadata', restore);
  }, [source, progress]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video || !source) return undefined;
    const persist = () => {
      if (!Number.isFinite(video.duration) || video.duration <= 0) return;
      savePlaybackProgress(identity, {
        currentTime: video.currentTime,
        duration: video.duration,
        title: metadata.title,
        backdrop: metadata.backdrop,
      });
    };
    const interval = setInterval(persist, 5000);
    video.addEventListener('pause', persist);
    video.addEventListener('ended', persist);
    return () => {
      clearInterval(interval);
      video.removeEventListener('pause', persist);
      video.removeEventListener('ended', persist);
      persist();
    };
  }, [identity, metadata, source]);

  if (!source) return <div className='flex aspect-video items-center justify-center rounded-2xl border border-white/10 bg-black p-8 text-center text-neutral-400'>No authorized stream is available for this title yet.</div>;

  return (
    <div className='overflow-hidden rounded-2xl border border-white/10 bg-black shadow-2xl shadow-black/40'>
      <video key={source.url} ref={videoRef} src={source.url} controls playsInline preload='metadata' className='aspect-video w-full bg-black' poster={metadata.backdrop || ''}>
        {subtitles.map((track) => <track key={`${track.language}-${track.url}`} kind='subtitles' src={track.url} srcLang={track.language} label={track.label || track.language} default={Boolean(track.default)} />)}
      </video>
      <div className='flex flex-wrap items-center justify-between gap-3 border-t border-white/10 bg-neutral-950 p-3'>
        <div><p className='text-xs font-bold uppercase tracking-wider text-neutral-500'>Source</p><p className='text-sm font-semibold text-neutral-200'>{source.quality || 'Auto'} · {(source.language || 'Original').toUpperCase()} · {source.sourceType?.toUpperCase()}</p></div>
        {sources.length > 1 ? <select value={selectedIndex} onChange={(e) => setSelectedIndex(Number(e.target.value))} className='rounded-xl border border-white/10 bg-neutral-900 px-3 py-2 text-sm text-white'>{sources.map((item, index) => <option key={`${item.url}-${index}`} value={index}>{item.quality || 'Auto'} · {item.language || 'Original'}</option>)}</select> : null}
      </div>
      {notice ? <p className='border-t border-amber-400/20 bg-amber-400/10 px-4 py-3 text-sm text-amber-200'>{notice}</p> : null}
    </div>
  );
};

export default StreamingPlayer;
