import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, useLocation, useNavigate, useParams } from 'react-router-dom';
import { useSelector } from 'react-redux';
import useFetchDetails from '../../../hooks/useFetchDetails';
import { getDemoStream, getStreamSources, getTvEpisodes } from '../../../api/streamApi';
import StreamingPlayer from '../components/StreamingPlayer';
import ErrorState from '../../../components/ui/ErrorState';
import Skeleton from '../../../components/ui/Skeleton';
import Button from '../../../components/ui/Button';

const WatchPage = ({ demo = false }) => {
  const params = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const mediaType = demo ? 'demo' : location.pathname.startsWith('/watch/tv/') ? 'tv' : 'movie';
  const id = demo ? 0 : Number(params.id);
  const season = Number(params.season || 0);
  const episode = Number(params.episode || 0);
  const imageURL = useSelector((state) => state.movieData.imageURL);
  const detailsEndpoint = demo ? '' : `/${mediaType}/${id}`;
  const { data: details } = useFetchDetails(detailsEndpoint);
  const [streamData, setStreamData] = useState(null);
  const [episodes, setEpisodes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    try {
      setLoading(true); setError(null);
      const response = demo ? await getDemoStream() : await getStreamSources(mediaType, id, mediaType === 'tv' ? { season, episode } : {});
      setStreamData(response.data?.data || null);
      if (!demo && mediaType === 'tv' && season) {
        const episodeResponse = await getTvEpisodes(id, season);
        setEpisodes(episodeResponse.data?.data?.episodes || []);
      }
    } catch (requestError) {
      setError(requestError);
    } finally { setLoading(false); }
  }, [demo, mediaType, id, season, episode]);

  useEffect(() => { load(); }, [load]);

  const title = demo ? 'Moventra Player Demo' : details?.title || details?.name || streamData?.title || 'Watch';
  const backdrop = demo ? '' : details?.backdrop_path ? `${imageURL}${details.backdrop_path}` : '';
  const identity = useMemo(() => ({ mediaType, tmdbId: id, season, episode }), [mediaType, id, season, episode]);

  if (loading) return <div className='mx-auto w-full max-w-[1400px] px-4 py-10 sm:px-6 lg:px-10'><Skeleton className='aspect-video w-full' /></div>;
  if (error) return <div className='mx-auto w-full max-w-[1400px] px-4 py-10 sm:px-6 lg:px-10'><ErrorState message='Unable to load the stream right now.' onRetry={load} /></div>;

  const currentEpisodeIndex = episodes.findIndex((item) => Number(item.episode) === episode);
  const previousEpisode = currentEpisodeIndex > 0 ? episodes[currentEpisodeIndex - 1] : null;
  const nextEpisode = currentEpisodeIndex >= 0 && currentEpisodeIndex < episodes.length - 1 ? episodes[currentEpisodeIndex + 1] : null;

  return (
    <div className='mx-auto w-full max-w-[1400px] px-4 py-8 sm:px-6 lg:px-10'>
      <div className='mb-5 flex flex-wrap items-end justify-between gap-4'>
        <div><p className='text-xs font-black uppercase tracking-[0.24em] text-red-500'>{demo ? 'Legal sample stream' : mediaType === 'tv' ? `Season ${season} · Episode ${episode}` : 'Movie playback'}</p><h1 className='mt-2 text-2xl font-black text-white sm:text-3xl'>{title}</h1></div>
        {!demo ? <Link to={`/${mediaType}/${id}`} className='text-sm font-bold text-neutral-400 hover:text-white'>Back to details</Link> : null}
      </div>

      <StreamingPlayer sources={streamData?.sources || []} subtitles={streamData?.subtitles || []} identity={identity} metadata={{ title, backdrop }} />

      <div className='mt-6 rounded-2xl border border-white/10 bg-white/[0.03] p-5'>
        <p className='text-sm leading-6 text-neutral-400'>{streamData?.licenseNote || 'Moventra only plays streams configured by the application owner. Add content you own, public-domain media, or properly authorized sources.'}</p>
      </div>

      {mediaType === 'tv' && episodes.length ? <section className='mt-8'><h2 className='text-xl font-black text-white'>Episodes</h2><div className='mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3'>{episodes.map((item) => <button key={item.episode} type='button' onClick={() => navigate(`/watch/tv/${id}/${season}/${item.episode}`)} className={`rounded-xl border p-4 text-left transition ${Number(item.episode) === episode ? 'border-red-500 bg-red-500/10' : 'border-white/10 bg-white/[0.03] hover:bg-white/[0.07]'}`}><p className='text-xs font-bold text-neutral-500'>EPISODE {item.episode}</p><p className='mt-1 font-bold text-white'>{item.title || `Episode ${item.episode}`}</p></button>)}</div><div className='mt-5 flex gap-3'>{previousEpisode ? <Button variant='secondary' onClick={() => navigate(`/watch/tv/${id}/${season}/${previousEpisode.episode}`)}>Previous Episode</Button> : null}{nextEpisode ? <Button onClick={() => navigate(`/watch/tv/${id}/${season}/${nextEpisode.episode}`)}>Next Episode</Button> : null}</div></section> : null}
    </div>
  );
};

export default WatchPage;
